// We need to insert before the closing },

let lines = src.split\('\\\\n'\);
let inCards = false;
let currentId = null;
let modified = 0;

for \(let i = 0; i < lines.length; i++\) {
  const line = lines[i];

  // Detect card id
  const idMatch = line.match\(/\\\\{id:\\"\([a-z0-9-]+\)\\"/\);
  if \(idMatch\) currentId = idMatch[1];

  // Find lines ending card objects \(contain earn:{...} and end with },\)
  // These lines end with }, or },confidence:\\"...\\"},
  if \(currentId && /earn:\\\\{/.test\(line\) && /\\\\},?\\\\s*$/.test\(line\)\) {
    const data = cardData[currentId];
    const fields = data || { retentionOffers: [], downgradePaths: [], ifYouCancel: null };

    // Build the fields string
    const ro = JSON.stringify\(fields.retentionOffers\);
    const dp = JSON.stringify\(fields.downgradePaths\);
    const iyc = fields.ifYouCancel ? JSON.stringify\(fields.ifYouCancel\) : 'null';
    const suffix = ',\\\\n retentionOffers:' + ro + ',\\\\n downgradePaths:' + dp + ',\\\\n ifYouCancel:' + iyc;

    // Insert before the final },
    if \(line.trimEnd\(\).endsWith\('},'\)\) {
      lines[i] = line.trimEnd\(\).slice\(0, -2\) + suffix + '},';
    } else if \(line.trimEnd\(\).endsWith\('}'\)\) {
      lines[i] = line.trimEnd\(\).slice\(0, -1\) + suffix + '}';
    }

    modified++;
    currentId = null;
  }
}

